import re
import sys

for f in sys.argv[1:]:
    h = open(f).read()
    print("==", f, re.findall(r'<h2>.*?</h2>', h)[:2], re.findall(r'name="revision" value="\d+"', h))
    for name in ['bore', 'stroke', 'mounting', 'certification', 'material']:
        m = re.search(r'<select name="' + name + r'"[^>]*>(.*?)</select>', h, re.S)
        s = re.sub(r'\s+', ' ', m.group(0)) if m else None
        if s and name == 'bore':
            s = str(re.findall(r'<option value="\w*" selected', s))
        print(' ', name, s[:700] if s else s)
    for m in re.finditer(r'role="alert"[^>]*>(.*?)</', h, re.S):
        print('  ALERT', m.group(1)[:400])
    for m in re.finditer(r'<input name="(\w+)" value="([^"]*)"', h):
        print('  IN', m.groups())

